<include file="Public:header"/><style type="text/css">    .table-list th{        width: 8%;    }</style><div class="mainbox">    <div id="nav" class="mainnav_title">        <ul>            <a href="{pigcms{:U('Qiye/lists')}">企业列表</a>|            <a href="javascript:void(0);" class="on">消费数据</a>        </ul>    </div>    <!-- {pigcms{:L_("内容头部")} -->    <div class="page-content" style="padding: 10px">        <div class="page-content-area">            <div class="row">                <div class="form-group" style="margin-bottom:0px">                    <form action="{pigcms{:U('Qiye/trade')}" method="get" id="myform1">                        <input type="hidden" name="c" value="Qiye"/>                        <input type="hidden" name="a" value="trade"/>                        <input type="hidden" name="qiye_id" value="{pigcms{$qiye_id}"/>                        <span class="fl">{pigcms{:L_("业务类型：")}</span>                        <select class="fl" id="type" name="type">                            <volist name="type_name" id="vo">                                <option value="{pigcms{$key}"                                <if condition="$key eq $_GET['type']">selected="selected"</if>                                >{pigcms{$vo}</option>                            </volist>                        </select>                        <span class="fl">{pigcms{:L_("日期筛选：")}</span>                        <input type="text" class="input-text fl" name="begin_time" style="width:120px;" id="d4311"                               value="{pigcms{$_GET.begin_time}"                               onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                        <input type="text" class="input-text fl" name="end_time" style="width:120px;" id="d4311"                               value="{pigcms{$_GET.end_time}"                               onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                        <div class="fl time-choice-wrap cf stat-time-choice" style="float: left;">                            <span class="time-btn time-choice  <if condition=" $_GET['selectTimeType'] eq                            1">time-current</if>" timetype="1" id="choice-today">                            {pigcms{:L_("今天")}</span>                            <span class="time-btn time-choice bor-gray <if condition=" $_GET['selectTimeType'] eq                            7">time-current</if>" id="choice-week" timetype="7" >                            {pigcms{:L_("近7天")}</span>                            <span class="time-btn time-choice <if condition=" $_GET['selectTimeType'] eq                            30">time-current</if>" id="choice-month" timetype="30" >                            {pigcms{:L_("近30天")}</span>                            <input type="hidden" id="_selectTimeType" name="selectTimeType"                                   value="{pigcms{$_GET['selectTimeType']}">                        </div>                        <input type="submit" value="{pigcms{:L_(" 查询")}" class="button"/>　　                        <input type="reset" id="reset" value="{pigcms{:L_(" 清空")}" class="button"/>                    </form>                </div>                <div class="col-xs-12" style="padding-left:0px;padding-right:0px;">                    <div class="white-bg receivables-statist cf" style="padding: 0px 5	px;margin-bottom: 15px;">                        <h3 class="payment-titile clearfix" style="font-size:16px;">                            <span class="title-text">{pigcms{:L_("关键指标")}</span>                        </h3>                        <div class="statist-wrap-list">                            <div class="statist-wrap fl" style="float:left;margin-right:50px;">                                <p><span class="statist-wrap-title sta-total">{pigcms{:L_("已消费应结算金额")}</span></p>                                <p class="sta-mon"><php>echo round($total_qiye_pay+$service_charge,2);</php></php>                                <p class="sta-num">{pigcms{$order_count}{pigcms{:L_("笔")}</p>                            </div>                            <div class="statist-wrap fl" style="float:left;margin-right:50px;">                                <p><span class="statist-wrap-title sta-trade">{pigcms{:L_("消费金额")}</span></p>                                <p class="sta-mon">{pigcms{$total_qiye_pay|round=###,2}</p>                                <p class="sta-num">{pigcms{$order_count}{pigcms{:L_("笔")}</p>                            </div>                            <div class="statist-wrap fl statist-wrap-spe" style="float:left">                                <p><span class="statist-wrap-title sta-refund">{pigcms{:L_("手续费")}</span></p>                                <p class="sta-mon">{pigcms{$service_charge|round=###,2}</p>                                <p class="sta-num">{pigcms{$order_count}{pigcms{:L_("笔")}</p>                            </div>                        </div>                    </div>                    <div class="table-list">                        <table width="100%" cellspacing="0">                            <thead>                            <tr>                                <th>{pigcms{:L_("日期")}</th>                                <th>{pigcms{:L_("消费金额（元）")}</th>                                <th>{pigcms{:L_("消费笔数")}</th>                                <th>{pigcms{:L_("应付手续费（元）")}</th>                                <th>{pigcms{:L_("应结算金额（元）")}</th>                            </thead>                            <tbody>                            <if condition="is_array($sale_date)">                                <volist name="sale_date" id="vo">                                    <tr>                                        <td>{pigcms{$vo.date_time}</td>                                        <td>{pigcms{$vo.total_qiye_pay|floatval}</td>                                        <td>{pigcms{$vo.count}</td>                                        <td>{pigcms{$vo.total_service_charge|floatval}</td>                                        <td><php>echo round($vo['total_qiye_pay'] + $vo['total_service_charge'],2);</php></td>                                    </tr>                                </volist>                                <tr>                                    <td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td>                                </tr>                                <else/>                                <tr>                                    <td class="textcenter red" colspan="9">{pigcms{:L_("列表为空！")}</td>                                </tr>                            </if>                            </tbody>                        </table>                    </div>                </div>            </div>        </div>    </div></div><style>    .statist-wrap {        width: 15%;        margin-right: 2.3%;        padding: 0 15px;        border: 1px solid #ccc;        border-radius: 5px;        margin-bottom: 15px    }    .sta-mon {        font-size: 25px;        color: #333;        width: 100%;        text-align: center;        white-space: nowrap;        overflow: hidden;        text-overflow: ellipsis;        line-height: 1    }    .sta-num {        font-size: 18px;        color: #999;        width: 100%;        text-align: center;        white-space: nowrap;        overflow: hidden;        text-overflow: ellipsis    }    .sta-total {        background: #1c84c6;        padding: 2px 7px;        color: #fff    }    .sta-trade {        background: #23c6c8;        padding: 2px 7px;        color: #fff    }    .sta-refund {        background: #ed5565;        padding: 2px 7px;        color: #fff    }    .time-choice-wrap {        margin: 0 10px;        border-radius: 3px;        border: 1px solid #ccc    }    .time-choice {        float: left;        display: block;        padding: 0 10px;        line-height: 29px;        font-size: 12px;        color: #333;        outline: 0;        cursor: pointer    }    .time-choice.time-current {        color: #fff;        background: #1ab394    }    .bor-gray {        border-left: 1px solid #ccc;        border-right: 1px solid #ccc    }    .fl {        margin-right: 5px;        margin-bottom: 5px;    }    .plat_form {        display: none;    }</style><script type="text/javascript" src="./static/js/artdialog/jquery.artDialog.js"></script><script type="text/javascript" src="./static/js/artdialog/iframeTools.js"></script><script>    $(function () {        if ($('#type').val() == 'shop') {            $('.plat_form').show()        }        $('#type').change(function () {            console.log($(this).val())            if ($(this).val() == 'shop') {                $('.plat_form').show()            } else {                $('.plat_form').hide()            }        })        $('#reset').click(function () {            window.location.href = "{pigcms{:U(trade)}";        })        $('#layer-tip').on('mouseover', function () {            console.log(111)            //$('.com-layer-text').show();            layer.tips($('.com-layer-text').html(), '#layer-tip', {                tips: 1            });        });        $('#layer-tip').on('mouseout', function () {            layer.closeAll()        });        $('.time-btn').click(function () {            $('.time-btn').removeClass('time-current')            $(this).addClass('time-current');            $('input[name="begin_time"]').val('')            $('input[name="end_time"]').val('')            $('#_selectTimeType').val($(this).attr('timetype'))            $('#myform1').submit();        })        $('input:radio').click(function () {            var obj = $(this);            if ($(obj).attr('name') == 'staff_list') {                var title = '{pigcms{:L_("选择店员")}'            } else {                var title = '{pigcms{:L_("选择店铺")}'            }            var type = $(obj).data('type')            if (type == 'part_staff' || type == 'part_store') {                if (type == 'part_store') {                    window.o2oTop.art.dialog.data('store_list', $(obj).val());                    var href = $(obj).attr('href') + '&type' + type + '&store_list=' + $(obj).val();                    $('#edit_store').show();                } else {                    window.o2oTop.art.dialog.data('staff_list', $(obj).val());                    var href = $(obj).attr('href') + '&type' + type + '&staff_list=' + $(obj).val() + '&store_list=' + $('#part_store').val();                    $('#edit_staff').show();                }                window.o2oTop.art.dialog.open(href, {                    init: function () {                        var iframe = this.iframe.contentWindow;                        window.o2oTop.art.dialog.data('iframe_handle', iframe);                    },                    id: type,                    title: title,                    padding: 0,                    width: 600,                    height: 500,                    lock: true,                    resize: false,                    background: 'black',                    button: null,                    fixed: false,                    close: null,                    left: '50%',                    top: '38.2%',                    opacity: '0.4',                    close: function () {                        if (type == 'part_staff') {                            var staff_list = window.o2oTop.art.dialog.data('staff_list');                            $(obj).val(staff_list)                        } else {                            var store_list = window.o2oTop.art.dialog.data('store_list');                            $(obj).val(store_list)                            $('#part_staff').val(0)                            $("input[name='staff_list']:eq(0)").attr("checked", 'checked');                            $("input[name='staff_list']:eq(1)").removeAttr("checked");                            $('#edit_staff').hide();                        }                    }                });            } else {                if (type == 'all_store') {                    $('#edit_store').hide();                } else {                    $('#edit_staff').hide();                }            }        })        $('#edit_store').click(function () {            var obj = $('#part_store');            var title = '{pigcms{:L_("选择店铺")}'            var type = $(obj).data('type')            window.o2oTop.art.dialog.data('store_list', $(obj).val());            var href = $(obj).attr('href') + '&type' + type            window.o2oTop.art.dialog.open(href, {                init: function () {                    var iframe = this.iframe.contentWindow;                    window.o2oTop.art.dialog.data('iframe_handle', iframe);                },                id: type,                title: title,                padding: 0,                width: 600,                height: 500,                lock: true,                resize: false,                background: 'black',                button: null,                fixed: false,                close: null,                left: '50%',                top: '38.2%',                opacity: '0.4',                close: function () {                    var store_list = window.o2oTop.art.dialog.data('store_list');                    $(obj).val(store_list)                    $('#part_staff').val(0)                    $("input[name='staff_list']:eq(0)").attr("checked", 'checked');                    $("input[name='staff_list']:eq(1)").removeAttr("checked");                    $('#edit_staff').hide();                }            });        })        $('#edit_staff').click(function () {            var obj = $('#part_staff');            var title = '{pigcms{:L_("选择店员")}'            var type = $(obj).data('type')            window.o2oTop.art.dialog.data('staff_list', $(obj).val());            var href = $(obj).attr('href') + '&type' + type + '&staff_list=' + $(obj).val() + '&store_list=' + $('#part_store').val();            window.o2oTop.art.dialog.open(href, {                init: function () {                    var iframe = this.iframe.contentWindow;                    window.o2oTop.art.dialog.data('iframe_handle', iframe);                },                id: type,                title: title,                padding: 0,                width: 600,                height: 500,                lock: true,                resize: false,                background: 'black',                button: null,                fixed: false,                close: null,                left: '50%',                top: '38.2%',                opacity: '0.4',                close: function () {                    var staff_list = window.o2oTop.art.dialog.data('staff_list');                    $(obj).val(staff_list)                }            });        })    });    // $('#merchant_worker_id').change(function(){    // var merchant_worker_id = $(this).val();    // var Url="{pigcms{:U('Appoint/order_list')}"+'&merchant_worker_id='+merchant_worker_id;    // location.href=Url;    // });    var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Analysis/export')}"</script><include file="Public:footer"/>